"""Profiled free Bundle caps on the existing physical terminal boundary segments.

This optional constructor extends the body's same transverse profile across
the finite cap footprint. A seam is accepted only if the independently computed
height agrees with the supplied body; exact original XYZ then wins by identity.
Longitudinal outer curbs have datum height. Free transverse cuts retain their
cross-section, including the small exposed step of unequal member endpoints.
"""
import bpy
from .path_surface_nodes import _Nodes
from . import bundle_cap_surface_nodes as planar, boundary_quad_bridge_nodes as bridge

NAME = 'Prochitecture Streets / Profiled physical Bundle free cap v2'


def profile(g, boundaries, axis, at_end, position):
    """Continue the four certified first/last straight boundary pieces.

    Sampling a Curve in LENGTH mode would clamp outside its domain. The cap
    needs the actual common-fibre intersections with these affine pieces.
    Validity is evaluated over the emitted cap; it does not authorize extending
    its footprint beyond the independently checked finite pavement union.
    """
    hits, checks = [], []
    for boundary in boundaries:
        count = bridge._size(g, boundary)
        end = g.math('SUBTRACT', count, 1.)
        i = g.switch(at_end, 0, end, 'INT')
        j = g.switch(at_end, 1, g.math('SUBTRACT', end, 1.), 'INT')
        field = g.named('st_axis_xy', 'FLOAT_VECTOR')
        first = g.sample(boundary, field, i, 'FLOAT_VECTOR')
        second = g.sample(boundary, field, j, 'FLOAT_VECTOR')
        delta = g.vector('SUBTRACT', second, first)
        advance = g.vector('DOT_PRODUCT', delta, axis)
        t = g.math('DIVIDE', g.vector('DOT_PRODUCT', g.vector('SUBTRACT', position, first), axis), advance)
        hits.append(g.vector('ADD', first, g.vector('SCALE', delta, t)))
        checks += [g.compare(count, 2, 'GREATER_EQUAL', 'INT'),
                   g.compare(g.math('ABSOLUTE', advance), 1e-5, 'GREATER_THAN')]
    oa, ia, ib, ob = hits
    fibre = g.vector('SUBTRACT', ob, oa)
    span = g.vector('LENGTH', fibre)
    normal = g.vector('NORMALIZE', fibre)
    a = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', ia, oa), normal)
    b = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', ib, oa), normal)
    q = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', position, oa), normal)
    right = g.math('SUBTRACT', span, b)
    denominator = g.math('ADD', g.math('MULTIPLY', a, a), g.math('MULTIPLY', right, right))
    left_penalty = g.math('DIVIDE', g.math('MAXIMUM', 0., g.math('SUBTRACT', a, q)), g.math('MAXIMUM', 1e-6, a))
    right_penalty = g.math('DIVIDE', g.math('MAXIMUM', 0., g.math('SUBTRACT', q, b)), g.math('MAXIMUM', 1e-6, right))
    penalty = g.math('ADD', g.math('MULTIPLY', left_penalty, left_penalty), g.math('MULTIPLY', right_penalty, right_penalty))
    overlap = g.math('MAXIMUM', 0., g.math('SUBTRACT', a, b))
    peak = g.math('SUBTRACT', 1., g.math('DIVIDE', g.math('MULTIPLY', overlap, overlap), g.math('MAXIMUM', 1e-6, denominator)))
    crown = g.math('MAXIMUM', 0., g.math('MINIMUM', 1.,
        g.math('DIVIDE', g.math('SUBTRACT', 1., penalty), g.math('MAXIMUM', .5, peak))))
    checks += [g.compare(a, 1e-6, 'GREATER_THAN'), g.compare(right, 1e-6, 'GREATER_THAN'),
               g.compare(b, 0., 'GREATER_EQUAL'), g.compare(a, span, 'LESS_EQUAL'),
               g.compare(q, -bridge.TOLERANCE, 'GREATER_EQUAL'),
               g.compare(q, g.math('ADD', span, bridge.TOLERANCE), 'LESS_EQUAL')]
    return crown, g.math('SUBTRACT', b, a), g.all(*checks)


def build(*, narrow_fill=False, finite_contact=False):
    if finite_contact and not narrow_fill:
        raise ValueError('Finite contact caps require the narrow-infill interface')
    name=NAME+' / narrow paved infill v1' if narrow_fill else NAME
    if finite_contact:name+=' / finite inner contact v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    tree = bpy.data.node_groups.new(name, 'GeometryNodeTree'); g = _Nodes(tree)
    sockets = [('Boundary '+str(k), 'Geometry', None) for k in range(4)]+[
        ('Seam', 'Geometry', None), ('Axis', 'Vector', (1., 0., 0.)),
        ('At End', 'Bool', False), ('Maximum Depth', 'Float', .5),
        ('Cell Size', 'Float', .17), ('Datum', 'Float', 0.), ('Rise', 'Float', .12),
        ('Height Exaggeration', 'Float', 1.)]
    if narrow_fill:sockets.append(('Minimum Separator Width','Float',.12))
    for name, kind, default in sockets:
        socket = tree.interface.new_socket(name=name, in_out='INPUT', socket_type='NodeSocket'+kind)
        if default is not None: socket.default_value = default
    for name, kind in (('Geometry', 'Geometry'), ('Valid', 'Bool'), ('Diagnostic Code', 'Int'),
                       ('Maximum Height Disagreement', 'Float')):
        tree.interface.new_socket(name=name, in_out='OUTPUT', socket_type='NodeSocket'+kind)
    inp = g.node('NodeGroupInput', 'Original boundary pieces and exact body seam')
    out = g.node('NodeGroupOutput', 'Profiled direct quad cap')
    cap = g.node('GeometryNodeGroup', 'Automatically selected conforming planar cap')
    cap.node_tree = planar.build(prescribed_seam=True, bounded_grading=True,narrow_fill=narrow_fill,
                                 finite_contact=finite_contact)
    for name in ('Seam', 'Axis', 'At End', 'Maximum Depth', 'Cell Size', *(('Boundary '+str(k)) for k in range(4))):
        g.set(inp.outputs[name], cap.inputs[name])
    if narrow_fill:g.set(inp.outputs['Minimum Separator Width'],cap.inputs['Minimum Separator Width'])
    mesh = cap.outputs['Planar World Geometry']
    pos = g.node('GeometryNodeInputPosition', 'Physical cap position').outputs[0]
    crown, gap, profile_ok = profile(g, [inp.outputs['Boundary '+str(k)] for k in range(4)],
                                   inp.outputs['Axis'], inp.outputs['At End'], pos)
    height = g.math('ADD', inp.outputs['Datum'], g.math('MULTIPLY', inp.outputs['Height Exaggeration'],
                    g.math('MULTIPLY', inp.outputs['Rise'], crown)))
    body_id = g.named('st_cap_body_index')
    pinned = g.compare(body_id, 0, 'GREATER_EQUAL', 'INT')
    original = g.sample(inp.outputs['Seam'], pos, body_id, 'FLOAT_VECTOR')
    error = g.stat(mesh, g.switch(pinned, 0., g.math('ABSOLUTE',
        g.math('SUBTRACT', height, g.component(original, 'Z')))), output='Max')
    valid = g.all(cap.outputs['Valid'], g.stat(mesh, profile_ok),
        g.compare(inp.outputs['Rise'], 0., 'GREATER_EQUAL'),
        g.compare(inp.outputs['Height Exaggeration'], 0., 'GREATER_EQUAL'),
        g.compare(error, bridge.TOLERANCE, 'LESS_EQUAL'))
    mesh = g.store(mesh, 'st_bundle_crown', crown)
    mesh = g.store(mesh, 'st_bundle_gap', gap)
    mesh = g.store(mesh, 'st_bundle_plateau_width', g.math('MAXIMUM', gap, 0.))
    xyz = g.xyz(g.component(pos, 'X'), g.component(pos, 'Y'), height)
    mesh = bridge._position(g, mesh, g.switch(pinned, xyz, original, 'VECTOR'))
    g.set(g.switch(valid, None, mesh, 'GEOMETRY'), out.inputs['Geometry'])
    g.set(valid, out.inputs['Valid']); g.set(error, out.inputs['Maximum Height Disagreement'])
    code = g.switch(cap.outputs['Valid'], cap.outputs['Diagnostic Code'], 4, 'INT')
    g.set(g.switch(valid, code, 0, 'INT'), out.inputs['Diagnostic Code'])
    return tree


def assemble(g, body, boundaries, axis, rows, cell_size, datum, rise, exaggeration, material, face_values,
             *, narrow_fill=False, minimum_band=None, finite_contact=False, cap_ends=None, maximum_depth=None):
    """Attach selected caps using semantic body rows and exact vertex identities.

    ``face_values(end)`` supplies the caller's ownership metadata. Source
    geometry, topology and profile decisions remain outside this small helper.
    No nearest-position search discovers or welds a physical seam.
    Optional per-end selection must match the body cuts; an inactive cap adds
    neither geometry nor a seam subtraction to the welded vertex-count check.
    """
    if narrow_fill and minimum_band is None:
        raise ValueError('Narrow paved caps require the actual separator width threshold')
    index = g.node('GeometryNodeInputIndex', 'Welded body vertex identity').outputs[0]
    body = g.store(body, 'st_bundle_body_vertex', index, 'INT')
    body = g.store(body, '_bridge_key', g.xyz(index), 'FLOAT_VECTOR')
    body = g.store(body, 'st_bundle_free_cap', 0, 'INT', 'FACE')
    pieces = [body]; checks = []; seam_counts = []; cap_counts = []
    for end in (False, True):
        cut = g.node('GeometryNodeSeparateGeometry', 'Exact body end row' if end else 'Exact body start row')
        cut.domain = 'POINT'; g.set(body, cut.inputs['Geometry'])
        row = g.math('SUBTRACT', rows, 1.) if end else 0
        g.set(g.compare(g.named('st_bundle_body_row'), row, kind='INT'), cut.inputs['Selection'])
        active = cap_ends[int(end)] if cap_ends is not None else True
        seam = cut.outputs['Selection']
        seam_count = bridge._size(g, seam)
        seam_counts.append(g.switch(active, 0, seam_count, 'INT') if cap_ends is not None else seam_count)
        cap = g.node('GeometryNodeGroup', 'Profiled end cap' if end else 'Profiled start cap')
        cap.node_tree = build(narrow_fill=narrow_fill,finite_contact=finite_contact)
        for name, value in [('Boundary '+str(k), value) for k, value in enumerate(boundaries)]+[
            ('Seam', seam), ('Axis', axis), ('At End', end), ('Cell Size', cell_size),
            ('Datum', datum), ('Rise', rise), ('Height Exaggeration', exaggeration)]:
            g.set(value, cap.inputs[name])
        if narrow_fill:g.set(minimum_band,cap.inputs['Minimum Separator Width'])
        if maximum_depth is not None:g.set(maximum_depth,cap.inputs['Maximum Depth'])
        mesh = cap.outputs['Geometry']
        if cap_ends is not None:
            mesh = g.switch(active, None, mesh, 'GEOMETRY')
        checks.append(g.either(g.boolean('NOT', active), cap.outputs['Valid']) if cap_ends is not None else cap.outputs['Valid'])
        cap_counts.append(bridge._size(g, mesh))
        body_id = g.named('st_cap_body_index')
        pinned = g.compare(body_id, 0, 'GREATER_EQUAL', 'INT')
        original_id = g.sample(seam, g.named('st_bundle_body_vertex'), body_id, 'INT')
        mesh = g.store(mesh, '_bridge_key', g.switch(pinned, g.xyz(index, 2 if end else 1),
                                                   g.xyz(original_id), 'VECTOR'), 'FLOAT_VECTOR')
        mesh = g.store(mesh, 'st_bundle_free_cap', 2 if end else 1, 'INT', 'FACE')
        mesh = g.store(mesh, 'st_bundle_station', 1. if end else 0.)
        mesh = g.store(mesh, 'st_bundle_body_vertex', g.switch(pinned, -1, original_id, 'INT'), 'INT')
        for name, kind, value in face_values(end):
            mesh = g.store(mesh, name, value, kind, 'FACE')
        assign = g.node('GeometryNodeSetMaterial', 'Free cap pavement material')
        g.set(mesh, assign.inputs['Geometry']); g.set(material, assign.inputs['Material'])
        pieces.append(assign.outputs['Geometry'])
    joined = bridge._join(g, *pieces)
    welded, agreement = bridge._weld(g, joined, exact_reference=True)
    expected = bridge._size(g, body)
    for count, seam_count in zip(cap_counts, seam_counts):
        expected = g.math('ADD', expected, g.math('SUBTRACT', count, seam_count))
    checks += [agreement, g.compare(bridge._size(g, welded), expected, kind='INT')]
    # All vertices belong to a free Bundle: none is an attached junction mouth.
    # Keep nearby distinct cap features out of the parent's proximity weld.
    welded = g.store(welded, 'st_bundle_interior', True, 'BOOLEAN')
    welded = g.store(welded, 'st_mouth_vertex', False, 'BOOLEAN')
    for name in ('_bridge_key', '_bridge_physical', '_chart_seam_ok', 'st_cap_body_index',
                 'st_cap_body_height', 'st_cap_seam_index', 'st_cap_vertex_id'):
        remove = g.node('GeometryNodeRemoveAttribute', 'Remove cap construction data')
        remove.inputs['Name'].default_value = name; g.set(welded, remove.inputs['Geometry'])
        welded = remove.outputs['Geometry']
    return welded, g.all(*checks)
